it('should accept only one concurrent topic creation per user', async () => {
	const originalCreate = apiTopics.create;
	let signalFirst;
	let releaseFirst;
	let firstCall = true;
	const firstEntered = new Promise((resolve) => { signalFirst = resolve; });
	const firstCanFinish = new Promise((resolve) => { releaseFirst = resolve; });
	apiTopics.create = async (...args) => {
		if (firstCall) {
			firstCall = false;
			signalFirst();
			await firstCanFinish;
		}
		return originalCreate(...args);
	};

	const form = { cid: categoryObj.cid, title: 'Concurrent topic', content: 'One new topic' };
	const send = () => helpers.request('post', '/api/v3/topics', {
		form: form,
		jar: adminJar,
		json: true,
	});
	const [topicsBefore, categoryBefore, userTopicsBefore] = await Promise.all([
		db.getObjectField('global', 'topicCount'),
		db.getObjectField(`category:${categoryObj.cid}`, 'topic_count'),
		db.sortedSetCard(`cid:${categoryObj.cid}:uid:${adminUid}:tids`),
	]);

	try {
		const first = send();
		await firstEntered;
		const rejected = await Promise.all(Array.from({ length: 4 }, send));
		rejected.forEach(({ res, body }) => {
			assert.strictEqual(res.statusCode, 400);
			assert.strictEqual(body.status.code, 'bad-request');
		});

		releaseFirst();
		const accepted = await first;
		assert.strictEqual(accepted.res.statusCode, 200);
		assert.strictEqual(accepted.body.status.code, 'ok');
		assert.strictEqual(accepted.body.response.title, form.title);
		assert.strictEqual(Number(await db.getObjectField('global', 'topicCount')), Number(topicsBefore) + 1);
		assert.strictEqual(Number(await db.getObjectField(`category:${categoryObj.cid}`, 'topic_count')), Number(categoryBefore) + 1);
		assert.strictEqual(await db.sortedSetCard(`cid:${categoryObj.cid}:uid:${adminUid}:tids`), userTopicsBefore + 1);
	} finally {
		releaseFirst();
		apiTopics.create = originalCreate;
	}
});

